import sys

def solve() -> None:
    input = sys.stdin.readline
    T = int(input())
    for _ in range(T):
        # 读取 N, K
        N, K = map(int, input().split())
        # 关卡得分，1-index
        a = [0] + list(map(int, input().split()))
        # 前缀和
        prefix = [0] * (N + 1)
        for i in range(1, N + 1):
            prefix[i] = prefix[i - 1] + a[i]

        NEG_INF = -10**18
        # dp[i][j] 表示前 i 个关卡划分为 j 个阶段的最大总得分
        dp = [[NEG_INF] * (K + 1) for _ in range(N + 1)]
        dp[0][0] = 0

        # 枚举阶段编号 j
        for j in range(1, K + 1):
            # 该阶段的权值：奇数阶段为 1，偶数阶段为 2
            w = 1 if j % 2 == 1 else 2
            max_val = NEG_INF
            # i 至少为 j，保证每个阶段至少有一个关卡
            for i in range(j, N + 1):
                # 候选分界点 l = i - 1（前 j-1 个阶段覆盖前 i-1 个关卡）
                if i - 1 >= j - 1:
                    cand = dp[i - 1][j - 1] - w * prefix[i - 1]
                    if cand > max_val:
                        max_val = cand
                # 完成转移
                dp[i][j] = w * prefix[i] + max_val

        print(dp[N][K])

if __name__ == "__main__":
    solve()
